/// <reference types="vitest/importMeta" />
/*
 * Curated prose courses for the Learn-mode viewer.
 *
 * Pattern lifted from chessreps' Learn mode (see
 * docs/research/competitor-deep-dive.md §2). Each course has MULTIPLE
 * lines (chessreps' "X/N lines"), and each line is an ordered sequence
 * of LessonNodes — replayed left-to-right by the viewer with a
 * speech-bubble per node, board auto-advancing through opponent
 * replies, user clicking Next (or playing the move) to advance through
 * own-moves.
 *
 * Schema decision (see §6.2 of the deep-dive): we DON'T put prose on
 * RepMove rows. Instead courses live here as a versioned, code-reviewed
 * sidecar keyed by the same `openingId` (= Repertoire.sourceLabel) the
 * curated importer uses. Edit-without-touching-SRS-state is the win.
 *
 * Authoring rules (see §6.4 of the deep-dive):
 *   - 1-4 sentences per node. Hard cap.
 *   - Move references in **bold** (rendered to <strong> by the bubble).
 *   - Open with "Let's learn the X!" — exact template.
 *   - Name the move first ("**1.e4** — pawn to e4").
 *   - Then the strategic *why* ("controls e5/d5, frees bishop and queen").
 *   - One self-aware joke per opening intro is allowed; don't strain.
 *   - No headings, bullets, or markdown beyond bold.
 *   - Don't quote master games or stats.
 *
 * FEN authoring rules:
 *   - Every node's FEN is COMPUTED at module-load time by replaying SAN
 *     through chess.js, then normalised via normFen(). Hand-typed FENs
 *     are forbidden — the builder is the single source of truth.
 *   - The validator at the bottom (guarded by `import.meta.vitest`)
 *     re-derives every FEN at vitest-run time and asserts equality
 *     anyway, as a defence in depth.
 *
 * Mainlines must match `selectMainLine()` over book.ts so Learn lines
 * up with Drill. To re-derive: open book.ts, find the opening, walk
 * children picking heaviest weight at each step.
 */

import { Chess } from 'chess.js';
import { normFen } from './fen';
import { GENERATED_LINES } from './generated-lines';

// ────────────────────────────────────────────────────────────────────────
// Opening-name lookup (lichess-org/chess-openings TSV → JSON)
//
// `public/opening-names.json` is generated by `scripts/vendor-opening-names.ts`
// from the canonical Lichess opening database (CC0). Keys are normalised
// FENs (== TSV `epd` column == `normFen()` output). Values carry ECO + name
// + canonical PGN. Used internally to verify that lesson lines end on a
// real, named tabiya — not mid-air.
// ────────────────────────────────────────────────────────────────────────

export interface OpeningNameEntry {
  eco: string;
  name: string;
  pgn: string;
}

let _openingNames: Record<string, OpeningNameEntry> | undefined;

/**
 * Lazy loader. In the browser, fetches `/opening-names.json` synchronously
 * via XHR (only used at validator time, which is fine). In Node/vitest,
 * reads the file directly. Returns `{}` if the file is missing — callers
 * must treat the result as best-effort.
 */
function loadOpeningNames(): Record<string, OpeningNameEntry> {
  if (_openingNames !== undefined) return _openingNames;
  // Empty-by-default in browsers — the lookup is only meaningful at
  // vitest time, where the validator block reads `public/opening-names.json`
  // off disk. The lookup function exists in production for completeness
  // but always returns an empty result there.
  _openingNames = {};
  return _openingNames;
}

/**
 * Look up the canonical ECO + name for a normalised FEN. Returns
 * `undefined` if the position has no entry in the Lichess opening
 * database (or the JSON file hasn't been vendored yet).
 */
export function lookupOpeningName(normalisedFen: string): OpeningNameEntry | undefined {
  return loadOpeningNames()[normalisedFen];
}

export interface LessonNode {
  /** Normalised FEN of the position AFTER the move (use normFen). */
  fen: string;
  /** SAN of the move that led here (omit for the starting position). */
  san?: string;
  /** Plain-English prose explaining the move and its idea. 1–4 sentences. */
  text: string;
}

/**
 * One distinct variation within an opening (e.g. "Giuoco Piano",
 * "Najdorf"). Lines are the unit users select and progress through
 * — chessreps' "X/N lines" semantics.
 *
 * Lines may optionally be "deviations" — a sibling branch off another
 * line at a specific ply, modelling what to do when the opponent plays
 * something other than the parent's mainline move. Deviation lines:
 *   - Carry the same lead-up plies as their parent up to `deviationFromMove`,
 *     then branch with the alternative move.
 *   - Are surfaced indented under their parent in the line picker.
 *   - Drill at a lower weight than mainlines so the user doesn't see them
 *     constantly — see `LESSON_DEVIATION_EDGE_WEIGHT` in `import.ts`.
 *   - Were authored to lift the inline "Common deviations: ..." prose into
 *     navigable, drillable units (Phase 1b of the engagement-first design;
 *     see `docs/OPENING_EXPANSION_PLAN.md`).
 */
export interface OpeningLine {
  /** Unique within an opening, e.g. 'giuoco-piano'. */
  id: string;
  /** Human name, e.g. 'Giuoco Piano'. */
  name: string;
  /** One-sentence description for the line picker. */
  description: string;
  /** Sequenced lesson nodes for this line. Always starts with the intro node. */
  nodes: LessonNode[];
  /**
   * If set, this line is a "deviation" — a sibling branch off the parent
   * line at the ply named in `deviationFromMove`. The line picker renders
   * it indented under its parent with a small badge.
   */
  parentLineId?: string;
  /**
   * 1-based ply (= node index) at which the deviation branches from the
   * parent line. Set iff `parentLineId` is set. Diagnostic only — the
   * UI doesn't enforce this against the parent's actual moves; it's a
   * label like "deviation at White's 6th".
   */
  deviationFromMove?: number;
  /**
   * Provenance for auto-generated lines (Tier-A pipeline — see
   * docs/CONTENT_SOURCING_PLAN.md). When set, the line picker shows a
   * "draft" badge, the Drill mode de-prioritises it, and the Learn view
   * reminds the author the prose is template-generated and needs human
   * authoring before it ships as polished content. Hand-authored lines
   * leave this undefined.
   */
  generated?: { source: 'lichess-masters'; gamesAtTabiya: number };
}

export interface OpeningCourse {
  /** Matches the `sourceLabel` of the corresponding curated repertoire. */
  openingId: string;
  /** Course name, e.g. 'Italian Game'. */
  title: string;
  /** Short tagline shown on the course header card. */
  tagline: string;
  /** One or more lines; the first is treated as the default. */
  lines: OpeningLine[];
}

// FEN of the standard chess starting position, normalised.
const START_FEN_NORM = normFen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1');

// ────────────────────────────────────────────────────────────────────────
// Authoring helpers
//
// `LineSpec` is the human-authored shape. `buildLine` runs the SAN
// sequence through chess.js to compute every FEN, so authors only ever
// type SAN — never FEN strings. This eliminates drift risk between
// hand-typed FENs and the chess.js replay path used at runtime.
// ────────────────────────────────────────────────────────────────────────

interface MoveSpec {
  san: string;
  text: string;
}

interface LineSpec {
  id: string;
  name: string;
  description: string;
  /** Intro prose shown on the starting position. */
  intro: string;
  /** Ordered list of moves for this line. */
  moves: MoveSpec[];
  /** See `OpeningLine.parentLineId`. */
  parentLineId?: string;
  /** See `OpeningLine.deviationFromMove`. */
  deviationFromMove?: number;
}

function buildLine(spec: LineSpec): OpeningLine {
  const game = new Chess();
  const nodes: LessonNode[] = [{ fen: START_FEN_NORM, text: spec.intro }];
  for (const m of spec.moves) {
    // chess.js throws on illegal SAN, which surfaces author errors at
    // module-load time with a clear stack trace.
    game.move(m.san);
    nodes.push({ fen: normFen(game.fen()), san: m.san, text: m.text });
  }
  return {
    id: spec.id,
    name: spec.name,
    description: spec.description,
    nodes,
    ...(spec.parentLineId !== undefined ? { parentLineId: spec.parentLineId } : {}),
    ...(spec.deviationFromMove !== undefined ? { deviationFromMove: spec.deviationFromMove } : {}),
  };
}

// ────────────────────────────────────────────────────────────────────────
// Courses
// ────────────────────────────────────────────────────────────────────────

